  nc = `Eventos temáticos: %1$s`,
  rc = `Halloween 2022`,
  ic = `¿Es este evento para una actualización de tu juego para Halloween 2022? Si agregas nuevos mapas, apariencias, imágenes u otro contenido a tu juego para Halloween o realizas eventos de tiempo limitado con contenido especial, desafíos u otras actividades similares, nos encantaría saberlo. Estamos evaluando mejores formas de hacer que los eventos temáticos sean más conocidos para un público más amplio, pero primero necesitamos una mejor idea del tipo de actividad que los desarrolladores organizan en tus juegos (si corresponde) para celebrar las festividades. Haz clic en "on" debajo si este evento es sobre una actualización de tu juego para Halloween 2012.`,
