  ll = `Cápsulas de la tienda`,
  ul = `Estas cápsulas permiten que la tienda presente esta página de ofertas en los lugares donde normalmente se presentan los juegos: el carrusel de destacados y recomendados, los puntos de encuentro de la tienda y el carrito. Son las mismas cápsulas que un juego carga en la pestaña de recursos gráficos de su página de tienda, en los mismos tamaños.`,
  dl = `Puedes cargarlas todas de una vez. Una imagen se asigna a una cápsula automáticamente cuando sus dimensiones coinciden exactamente con esa cápsula; cualquier cosa diferente tendrás que asignarla tú mismo y se te pedirá recortarla. Puedes nombrar tus archivos de imagen para terminar con un nombre de idioma para que se clasifiquen como ese idioma (por ejemplo, "main_capsule_french.jpg").`,
  fl = `Enfócate en los logotipos de la oferta. Asegúrate de que el logotipo sea claramente legible.`,
