  Il = `Ingresa únicamente la parte de la dirección que sigue a la página principal de la tienda, sin la barra diagonal inicial. Por ejemplo, ingresa category/pins_pegs para enlazar con https://store.steampowered.com/category/pins_pegs.`,
  Ll = `Debe ser una referencia a la página principal de la tienda, así que omite el prefijo https://store.steampowered.com/. Por ejemplo, escribe: category/pins_pegs en lugar de https://store.steampowered.com/category/pins_pegs.`,
