  Ru = `Importar...`,
  zu = `Selecciona uno o más archivos para importar el texto localizado del título, el subtítulo, el resumen y la descripción. Utilizamos la extensión del archivo para determinar si se trata de una importación en XML o en CSV. Para el XML, usamos el código de idioma de la API al final del nombre de archivo —antes de la extensión— para determinar el idioma del contenido del archivo XML. Deberías comenzar por exportar el CSV o XML para asegurarte de que estás usando el formato correcto.`,
  Bu = `Importación de localización completada. Se actualizaron los siguientes idiomas: %1$s`,
