  Md = `No puedes publicar un evento con la categoría "Actualización importante" sin proporcionar también al menos un material gráfico clave en idioma inglés. La actualización importante se mostrará como destacada en el detalle para tu juego del cliente de escritorio de la biblioteca de Steam.`,
