  Bd = `Falta el material gráfico. Los eventos permiten incluir material gráfico personalizado que ayude a promocionar el evento y hacerlo más atractivo para los usuarios de Steam. Sin material gráfico, recurrimos a una imagen cápsula del juego.`,
  Vd = `Falta el material gráfico. Los eventos permiten material gráfico personalizado que ayude a promocionar el evento y lo haga más atractivo para los usuarios de Steam. De no haberlo, usaremos el avatar del grupo.`,
  Hd = `Si la categoría del evento se establece como "otra", reducirá considerablemente la visibilidad de este evento. Steam utiliza las categorías de eventos para ayudar a dirigir los eventos a los clientes de Steam. En la categoría "otra" se asume que están los eventos menos impactantes y se mostrarán a un número reducido de usuarios.`,
