  Wd = `Hay material gráfico específico en %1$s de los %2$s idiomas. Puedes ignorar esto si el material gráfico no necesita traducción. A los idiomas sin material gráfico se les aplicará el elegido para el inglés.`,
  Gd = `El tiempo de visibilidad se ha ajustado al pasado y, por lo tanto, guardar ahora hará que el evento sea visible. Una vez que está visible, la hora de inicio no se puede cambiar y el evento no se puede ocultar.`,
  Kd = `Hay imágenes de espacio destacado en la tienda cargadas para este evento, pero la marca de destacado está desactivada. Valve debe activar la marca de destacado para que el banner se muestre en tu página de la tienda.`,
  qd = `El URL de destino del logotipo de la página de ofertas no es relativo a la página de inicio de la tienda, por lo que al hacer clic en el logotipo, los clientes serán redirigidos a una página rota. Debería tener el formato category/pins_pegs, no https://store.steampowered.com/category/pins_pegs.`,
