  $h = `En la página de Workshop`,
  eg = `También puedes publicar este evento/anuncio en el Workshop de Steam para tu juego. Para habilitarlo, cambia a la pestaña "opciones" y selecciona "Publicar también en tu Workshop". Por defecto, los eventos/anuncios del juego no aparecen en la sección del Workshop.`,
  tg = `Estandarte de la página de producto de Steam`,
  ng = `Imagen de la página de producto visible desde el %1$s hasta el %2$s`,
  rg = `Puedes proporcionar un banner de las rebajas en la pestaña "Rebajas", lo que permite que los juegos destacados hagan referencia a la rebaja cuando se muestra la imagen proporcionada en la parte superior de la página del producto en Steam. Esto ayuda a los clientes de Steam a descubrir un descuento en un juego específico con un mensaje de la lista de deseados o al explorar la tienda para también saber más sobre eventos de rebajas más grandes. Estos banners solo estarán visibles desde el inicio de tu evento hasta el final o durante dos semanas, o lo que ocurra antes. El horario de los eventos se especifica en la pestaña "Opciones".`,
