  ay = `Minutos`,
  oy = `Esta entrada del calendario ya no coincide con el valor predeterminado. ¿Seguro que quieres eliminarla? Esta acción no se puede revertir`,
  sy = `Colecciones actuales`,
  cy = `Una colección vincula un grupo de eventos relacionados con una imagen de marca distintiva y un esquema de color. No es necesario que los eventos aparezcan en la programación. Por ejemplo, evento principal o colección artística.`,
