  hy = `Agrega eventos específicamente para esta colección. Solo serán válidos si están publicados, empiezan y terminan dentro del periodo programado y coinciden con el tipo de evento permitido para el programa.`,
  gy = `Acuerdos de eventos de rebajas`,
  _y = `Antes de poder utilizar las herramientas del editor de rebajas, debes aceptar los siguientes requisitos:`,
  vy = `Entiendo que la página de las rebajas debe describir claramente el grupo o las personas responsables de organizar las rebajas o el evento.`,
  yy = `Entiendo que no puedo garantizar a los participantes un nivel determinado de visibilidad en Steam, y que no puedo cobrar por visibilidad en la página.`,
  by = `Entiendo que Valve se reserva el derecho de modificar una página de rebajas que incluye, entre otras, la visibilidad de los juegos o retransmisiones en la página o el texto o las imágenes que describen el evento.`,
  xy = `Entiendo que Valve elige cuáles eventos promocionar dentro de la tienda de Steam y que mi evento puede no ser promocionado.`,
  Sy = `Entiendo que solo puedo agregar juegos a la página de ofertas para los que haya recibido permiso del desarrollador o editor. Los desarrolladores verán que su juego está incluido en mis ofertas tan pronto como lo agregue a mi página.`,
