  Sx = `Administrar 1 imagen`,
  Cx = `Administrar %1$s imágenes`,
  wx = `Agrega una imagen detallada de encabezado a la página de detalles para indicar el tema o la esencia del anuncio o actualización. Recuerda que es importante descargar las plantillas (enlace incluido en la parte superior de esta página) para asegurarte de que la imagen de encabezado tiene el diseño adecuado para las diferentes situaciones en las que se usa.`,
  Tx = `Vista previa de tu página de detalles:`,
  Ex = `Vista previa de la página emergente de tu evento:`,
  Dx = `Esta imagen aparecerá en el panel lateral al lado de tu retransmisión.`,
  Ox = `Los eventos o anuncios importantes pueden incluir una imagen de banner, que se muestra en tu página de la tienda hasta que el evento finaliza. El material gráfico de este banner es distinto del de otros lugares de la tienda. Valve debe aprobar estos banners; habla con tu contacto de Valve antes de cargarlos.`,
  kx = `Considera incluir una descripción breve y llamativa del evento en el banner de destacados para que los jugadores puedan saber, de un vistazo, qué tiene de interesante.`,
