  Mx = `Esta imagen aparecerá como fondo de tu página de ofertas. Puedes crear esta imagen como una imagen grande, o crear una casilla y configurarla como un patrón repetido.`,
  Nx = `El contenido crítico debe colocarse dentro del centro de 940 px de tu imagen. El material gráfico puede desangrarse hacia los lados y hacia abajo en la página, según lo desees. Por lo general, quieres que las ilustraciones se desvanezcan en un color sólido en los lados y la parte inferior y luego configurar el color de fondo de la página para que coincida. Mantén la imagen por debajo de 4 MB.`,
  Px = `Descargar todas las plantillas de la página de ofertas (archivos .psd)`,
  Fx = `La imagen de fondo de las ofertas funciona bien con el logo de la página de ofertas especificado a continuación. Si se usan juntos, el logo de tu página de ofertas flotará en la parte superior del fondo.`,
  Ix = `Plantillas`,
  Lx = `Esta imagen se superpondrá al fondo en la parte superior de tu página. Si deseas localizar las imágenes, envía un archivo .psd por correo electrónico a tu contacto de Valve.`,
  Rx = `Si se carga este banner, aparecerá en la página de la tienda de todos los juegos que participen en este evento de ofertas. Este banner aparecerá mientras dure el evento de ofertas, hasta un máximo de dos semanas. Ten en cuenta que Valve deberá aprobar el banner antes de que lo puedas usar y no puede ser animado.`,
  zx = `Esta versión solo aparece cuando la resolución de la página se reduce para un dispositivo móvil.`,
  Bx = `También puedes actualizar la imagen principal de tu biblioteca con la marca para tu actualización, anuncio, temporada u otro evento. Para hacerlo, ve a la pestaña "Recursos gráficos" en el administrador de la página de la tienda.`,
  Vx = `Diseño`,
  Hx = `Dimensiones`,
  Ux = `Uso`,
  Wx = `Obligatorio`,
  Gx = `Opcional`,
  Kx = `Esta imagen generalmente contiene material gráfico y marcas que representan tu evento, además de cualquier mensaje breve que quieras resaltar. Steam incluirá automáticamente el nombre y el ícono de tu juego junto a esta imagen en algunos contextos, pero te recomendamos que incluyas también el logotipo de tu juego en la imagen de portada, ya que esta imagen se usa cuando tu evento se comparte en las redes sociales.`,
  qx = `Esta aparecerá en los anuncios recientes de tu página de la tienda, en listas de eventos y anuncios y en tu página de detalles de la biblioteca. Esta imagen se utiliza para representar tu evento o anuncio en las redes sociales. El enlace de tu evento o anuncio posiblemente se muestre al lado del contenido de múltiples juegos, la imagen debe de ser clara y fácil de reconocer.`,
  Jx = `Esta imagen generalmente contiene material gráfico y branding que representa a tu editor, desarrollador o franquicia. Steam incluirá automáticamente tu ícono de avatar junto a esta imagen en algunos contextos.`,
  Yx = `También aparecerá en lugares de Steam donde aparece la página de inicio del creador y se usará para representar el evento cuando se comparta en redes sociales. La imagen debe ser clara y reconocible.`,
  Xx = `Imagen de banner para el enlace a lo mejor del año en las gráficas de Steam`,
  Zx = `Se muestra en las secciones de promoción cruzada de esta oferta, como la página de Descuentos y eventos, en lugar del logotipo de la página de ofertas. Si este logotipo no necesita localización, cárgalo de una vez, en inglés, y se usará en todos los idiomas.`,
  Qx = `Un logo que se renderiza en el área superior de tu imagen de fondo. Esta imagen debe contener el logo, las fechas y cualquier etiqueta de tu evento y tener un fondo transparente.`,
