  dT = `Esta es una lista de todos los artículos vinculados de las rebajas que actualmente no se encuentran en NINGUNA sección, ya sea explícitamente o incluidos a través de un filtro. Esto es útil para asegurarse de que todos los elementos estén visibles en unas rebajas y explorar agrupaciones de artículos no incluidos.`,
