  hT = `Esto proporciona una lista de todas las etiquetas contenidas en los artículos coincidentes y cuántas de cada uno hay. Esto es útil para determinar si puede haber otros desgloses de etiquetas disponibles. Cada etiqueta se puede seleccionar para ver qué artículos de la lista tienen la etiqueta asociada.`,
