  VT = `Esto se usará al final del URL para tu página de ofertas, a la que tus clientes llegan desde tu página de inicio de creador. No incluyas espacios en el URL o la codificación se complicará, es preferible que uses el guion bajo (_). Solo acepta caracteres, números, el guion (-) y el guion bajo (_) en este campo. Por ejemplo: Halloween2019, San_Valentin, LasMejoresRebajas`,
