  XD = `Recomendaciones y listas del mentor`,
  ZD = `Controla dónde aparecerán las recomendaciones o listas de destacados del mentor en la página. De forma predeterminada, los usuarios que siguen a los mentores de Steam verán sus recomendaciones sobre juegos destacados en las rebajas en la parte inferior de la página de rebajas. Esto te permite controlar dónde aparecerá esta sección.`,
  QD = `Muestra recomendaciones y listas de mentores. Extrae las listas automáticamente de los mentores que sigue el usuario en Steam y de la lista de mentores destacados, en el idioma del usuario en Steam, que siguen los usuarios de Steam.`,
  $D = `Opcional: Mostrar la hora de inicio`,
  eO = `Especifica de forma opcional una hora de inicio de cuándo la recomendación empezará a ser mostrada, potencialmente dando a los mentores algo de tiempo para crear sus listas antes de que sean visibles. Este tiempo está limitado entre la hora de inicio y la hora de finalización del evento.`,
