  hR = `Una sección de revelación dinámica es útil en conjunto con una retransmisión en directo de un anuncio. Esto permite a un operador agregar aplicaciones/paquetes/lotes visibles una vez que la rebaja sea pública y que sea visible en la página para los usuarios de Steam sin requerir actualizar la página. Recomendamos colocar esta sección junto al reproductor de la retransmisión. Asegúrate de solo agregar aplicaciones visibles o la página de la tienda almacenará en la caché que la aplicación no les es visible a los usuarios de Steam.`,
  gR = `Ocultar si hay pocos artículos`,
