  rY = `Automáticamente rellena las facetas y valores de facetas basado en categorías de etiquetas de la tienda, como "Género" y "Estilo visual y punto de vista". Después de que se genere automáticamente, podrás editar manualmente cada faceta y valor de faceta cuando sea necesario.`,
